async function savePart(partData: any): Promise<string> {
  const partId = uuidv4();
  const timestamp = new Date().toISOString();

  // Save metadata
  const metadata: any = {
    PK: `PART#${partId}`,
    SK: 'METADATA',
    name: partData.name,
    category: partData.category,
    manufacturer: partData.manufacturer,
    model: partData.model || '',
    vehicleBrand: partData.vehicleBrand || '',
    year: partData.year || 2020,
    condition: partData.condition || 'used',
    price: partData.price,
    quantity: partData.quantity || 1,
    sellerId: 'synthetic',
    description: partData.description || '',
    images: partData.images || [],
    specifications: {
      voltage: partData.specifications?.voltage,
      capacity: partData.specifications?.capacity,
      weight: partData.specifications?.weight,
    },
    createdAt: timestamp,
    updatedAt: timestamp,
    GSI1PK: `CATEGORY#${partData.category}`,
    GSI1SK: `CREATED_AT#${timestamp}`,
    GSI2PK: 'ALL#METADATA',
    GSI2SK: `CREATED_AT#${timestamp}`,
  };

  // 배터리 건강 정보 추가
  if (partData.batteryHealth) {
    metadata.batteryHealth = partData.batteryHealth;
  }

  // 검색 문서 (사양 포함 전체 레코드로 만들어 METADATA에 저장)
  metadata[SEARCH_TEXT_ATTRIBUTE] = buildSearchText(partData);
  metadata[SEARCH_ATTRIBUTES_ATTRIBUTE] = extractSearchAttributes(partData);
  metadata[SEARCH_DOC_VERSION_ATTRIBUTE] = SEARCH_DOCUMENT_VERSION;

  await putItem(metadata);

  // Save specifications
  if (partData.specifications) {
    await putItem({
      PK: `PART#${partId}`,
      SK: 'SPEC',
      ...partData.specifications,
    });
  }

  // Save use cases
  if (partData.useCases && Array.isArray(partData.useCases)) {
    for (let i = 0; i < partData.useCases.length; i++) {
      const usageId = `${i + 1}`.padStart(3, '0');
      await putItem({
        PK: `PART#${partId}`,
        SK: `USAGE#${usageId}`,
        ...partData.useCases[i],
      });
    }
  }

  // Generate and save embedding
  const embedding = await generateEmbedding(buildEmbeddingText(partData));

  // 레거시 S3 JSON 저장 (백업)
  const vectorKey = `parts/${partId}.json`;
  await uploadVector(vectorKey, embedding);
  await updateVectorsManifest([vectorKey]);

  // S3 Vectors 저장 (활성화된 경우)
  if (USE_S3_VECTORS && S3_VECTORS_BUCKET) {
    await uploadToS3Vectors(partId, embedding, {
      name: partData.name,
      category: partData.category,
      manufacturer: partData.manufacturer,
      price: partData.price,
      condition: partData.condition
    });
  }

  await putItem({
    PK: `PART#${partId}`,
    SK: 'VECTOR',
    s3Key: vectorKey,
    s3VectorsEnabled: USE_S3_VECTORS && S3_VECTORS_BUCKET ? true : false,
    embeddingModel: 'amazon.titan-embed-text-v2:0',
    dimension: embedding.length,
    createdAt: timestamp,
  });

  return partId;
}

