  try {
    const parsed = parseJsonBody(event);
    if (!parsed.ok) {
      return parsed.response;
    }
    const body = parsed.body;
    const { buyerId, email, phone, criteria } = body;

    // Validation
    if (!buyerId || !criteria) {
      return errorResponse('Missing required fields: buyerId, criteria', undefined, 400, event);
