 */
async function sendContactNotification(
  name: string,
  email: string,
  subject: string,
  message: string,
  partId?: string,
  partName?: string
): Promise<void> {
  const partInfo = partId && partName
    ? `\n부품 ID: ${partId}\n부품명: ${partName}\n`
    : '';

  const snsMessage = `
[EECAR 일반 문의]

문의자 이름: ${name}
문의자 이메일: ${email}
제목: ${subject}${partInfo}
문의 내용:
${message}

---
고객에게 회신이 필요합니다.
답변 이메일: ${email}
  `.trim();

  try {
    await snsClient.send(
